a = 1; L = 1; nau = 3;
f[x_, t_] = x (L - x); psi1[t_] = t^2; psi2[t_] = 0;
phi1[x_] = 0; phi2[x_] = 0;
u3[x_, t_] = psi1[t] + (x/L) (psi2[t] - psi1[t]);
g[x_, t_] = f[x, t] - D[u3[x, t], {t, 2}];
u10[x_] = phi1[x] - u3[x, 0];
du3[x_, t_] = D[u3[x, t], t];
du10[x_] = phi2[x] - du3[x, 0];
An[n_] := (2/L) Integrate[u10[x]*Sin[n*Pi*x/L], {x, 0, L}]
Bn[n_] := (2/(n*Pi*a)) Integrate[du10[x]*Sin[n*Pi*x/L], {x, 0, L}]
u1[x_, t_] := Sum[(An[n]*Cos[n*Pi*a*t/L] + Bn[n]*Sin[n*Pi*a*t/L])*Sin[n*Pi*x/L], {n, 1, nau}]
gn[n_, t_] := (2/L) Integrate[g[x, t]*Sin[n*Pi*x/L], {x, 0, L}]
u2[x_, t_] := Sum[(L/(n*Pi*a)) Integrate[gn[n, tau]*Sin[n*Pi*a*(t - tau)/L], {tau, 0, t}]*Sin[n*Pi*x/L], {n, 1, nau}]
u[x_, t_] = u1[x, t] + u2[x, t] + u3[x, t];
